  // `DatasetPreview`, `ViewPreview`, `ReportPreview`, `PagePreview`,
  // `PageBlockCanvas` and its add-block picker, `SourcePageEditor`,
  // `ValidationPreview`, the view column manager) and the federated
  // datasource panel, each en row the literal it replaces. Author data (names,
  // labels, messages, tags, region and slot names, CEL and regex sources) and
  // producer text (the error a renderer threw, an engine or HTTP message) stay
  // as written.
